-- case: MATCH (a)-[:EdgeKind1]->(b)-[:EdgeKind2]-(c) RETURN c
with s0 as (select e0.id as e0, n1.id as n1 from edge e0 join node n0 on n0.id = e0.start_id join node n1 on n1.id = e0.end_id where e0.kind_id = any (array [3]::int2[])), s1 as (select s0.e0 as e0, s0.n1 as n1, (n2.id, n2.kind_ids, n2.properties)::nodecomposite as n2 from s0 join edge e1 on (s0.n1 = e1.start_id or s0.n1 = e1.end_id) join node n2 on ((s0.n1 = e1.start_id and n2.id = e1.end_id) or (n2.id = e1.start_id and s0.n1 = e1.end_id)) where e1.kind_id = any (array [4]::int2[]) and e1.id != s0.e0) select s1.n2 as c from s1;

-- case: MATCH (a)<-[:EdgeKind1]-(b)-[:EdgeKind2]-(c) RETURN count(*) AS c
with s0 as (select e0.id as e0, (n1.id, n1.kind_ids, n1.properties)::nodecomposite as n1 from edge e0 join node n0 on n0.id = e0.end_id join node n1 on n1.id = e0.start_id where e0.kind_id = any (array [3]::int2[])), s1 as (select s0.e0 as e0, s0.n1 as n1 from s0 join edge e1 on ((s0.n1).id = e1.start_id or (s0.n1).id = e1.end_id) join node n2 on (((s0.n1).id = e1.start_id and n2.id = e1.end_id) or (n2.id = e1.start_id and (s0.n1).id = e1.end_id)) where e1.kind_id = any (array [4]::int2[]) and e1.id != s0.e0) select count(*)::int8 as c from s1;

-- case: MATCH (a)-[:EdgeKind1]-(b)-[:EdgeKind2]-(c) RETURN c
with s0 as (select e0.id as e0, n1.id as n1 from edge e0 join node n0 on (n0.id = e0.end_id or n0.id = e0.start_id) join node n1 on (n1.id = e0.end_id or n1.id = e0.start_id) where ((n0.id = e0.start_id and n1.id = e0.end_id) or (n1.id = e0.start_id and n0.id = e0.end_id)) and e0.kind_id = any (array [3]::int2[])), s1 as (select s0.e0 as e0, s0.n1 as n1, (n2.id, n2.kind_ids, n2.properties)::nodecomposite as n2 from s0 join edge e1 on (s0.n1 = e1.start_id or s0.n1 = e1.end_id) join node n2 on ((s0.n1 = e1.start_id and n2.id = e1.end_id) or (n2.id = e1.start_id and s0.n1 = e1.end_id)) where e1.kind_id = any (array [4]::int2[]) and e1.id != s0.e0) select s1.n2 as c from s1;

-- case: MATCH p = (a)-[:EdgeKind1]->(b)-[:EdgeKind2]-(c) RETURN p
with s0 as (select e0.id as e0, (n0.id, n0.kind_ids, n0.properties)::nodecomposite as n0, (n1.id, n1.kind_ids, n1.properties)::nodecomposite as n1 from edge e0 join node n0 on n0.id = e0.start_id join node n1 on n1.id = e0.end_id where e0.kind_id = any (array [3]::int2[])), s1 as (select s0.e0 as e0, e1.id as e1, s0.n0 as n0, s0.n1 as n1, (n2.id, n2.kind_ids, n2.properties)::nodecomposite as n2 from s0 join edge e1 on ((s0.n1).id = e1.start_id or (s0.n1).id = e1.end_id) join node n2 on (((s0.n1).id = e1.start_id and n2.id = e1.end_id) or (n2.id = e1.start_id and (s0.n1).id = e1.end_id)) where e1.kind_id = any (array [4]::int2[]) and e1.id != s0.e0) select case when (s1.n0).id is null or s1.e0 is null or (s1.n1).id is null or s1.e1 is null or (s1.n2).id is null then null else ordered_edge_ids_to_path(0, s1.n0, array [s1.e0]::int8[] || array [s1.e1]::int8[], array [s1.n0, s1.n1, s1.n2]::nodecomposite[])::pathcomposite end as p from s1;

-- case: MATCH (a)-[:EdgeKind1*0..2]->(b)-[:EdgeKind2]-(c) RETURN c
with s0 as (with recursive s1(root_id, next_id, depth, satisfied, is_cycle, path) as (select n0.id, n0.id, 0, false, false, array []::int8[] from node n0 union all select e0.start_id, e0.end_id, 1, false, false, array [e0.id] from edge e0 where e0.kind_id = any (array [3]::int2[]) union all select s1.root_id, e0.end_id, s1.depth + 1, false, false, s1.path || e0.id from s1 join lateral (select e0.id, e0.start_id, e0.end_id, e0.kind_id, e0.properties from edge e0 where e0.start_id = s1.next_id and e0.id != all (s1.path) and e0.kind_id = any (array [3]::int2[]) offset 0) e0 on true where s1.depth < 2 and not s1.is_cycle and s1.depth > 0) select s1.path as ep0, (n0.id, n0.kind_ids, n0.properties)::nodecomposite as n0, n1.id as n1 from s1 join lateral (select n0.id, n0.kind_ids, n0.properties from node n0 where n0.id = s1.root_id offset 0) n0 on true join lateral (select n1.id from node n1 where n1.id = s1.next_id offset 0) n1 on true), s2 as (select s0.ep0 as ep0, s0.n0 as n0, s0.n1 as n1, (n2.id, n2.kind_ids, n2.properties)::nodecomposite as n2 from s0 join edge e1 on (s0.n1 = e1.start_id or s0.n1 = e1.end_id) join node n2 on ((s0.n1 = e1.start_id and n2.id = e1.end_id) or (n2.id = e1.start_id and s0.n1 = e1.end_id)) where e1.kind_id = any (array [4]::int2[]) and e1.id != all (s0.ep0)) select s2.n2 as c from s2;

-- case: MATCH (a)-[:EdgeKind1]->(b)-[:EdgeKind2]-(c)-[:EdgeKind1]-(d) RETURN d
with s0 as (select e0.id as e0, n1.id as n1 from edge e0 join node n0 on n0.id = e0.start_id join node n1 on n1.id = e0.end_id where e0.kind_id = any (array [3]::int2[])), s1 as (select s0.e0 as e0, e1.id as e1, s0.n1 as n1, n2.id as n2 from s0 join edge e1 on (s0.n1 = e1.start_id or s0.n1 = e1.end_id) join node n2 on ((s0.n1 = e1.start_id and n2.id = e1.end_id) or (n2.id = e1.start_id and s0.n1 = e1.end_id)) where e1.kind_id = any (array [4]::int2[]) and e1.id != s0.e0), s2 as (select s1.e0 as e0, s1.e1 as e1, s1.n1 as n1, s1.n2 as n2, (n3.id, n3.kind_ids, n3.properties)::nodecomposite as n3 from s1 join edge e2 on (s1.n2 = e2.start_id or s1.n2 = e2.end_id) join node n3 on ((s1.n2 = e2.start_id and n3.id = e2.end_id) or (n3.id = e2.start_id and s1.n2 = e2.end_id)) where e2.kind_id = any (array [3]::int2[]) and e2.id != s1.e0 and e2.id != s1.e1) select s2.n3 as d from s2;

-- case: MATCH (a)-[:EdgeKind1]->(b)-[r:EdgeKind2]-(c) SET c.visited = true, r.visited = true RETURN c
-- pgsql_params:{"__strlit0":"visited"}
with s0 as (select e0.id as e0, n1.id as n1 from edge e0 join node n0 on n0.id = e0.start_id join node n1 on n1.id = e0.end_id where e0.kind_id = any (array [3]::int2[])), s1 as (select s0.e0 as e0, (e1.id, e1.start_id, e1.end_id, e1.kind_id, e1.properties)::edgecomposite as e1, s0.n1 as n1, (n2.id, n2.kind_ids, n2.properties)::nodecomposite as n2 from s0 join edge e1 on (s0.n1 = e1.start_id or s0.n1 = e1.end_id) join node n2 on ((s0.n1 = e1.start_id and n2.id = e1.end_id) or (n2.id = e1.start_id and s0.n1 = e1.end_id)) where e1.kind_id = any (array [4]::int2[]) and e1.id != s0.e0), s2 as (update node n3 set properties = n3.properties || jsonb_build_object(@__strlit0::text, true)::jsonb from s1 where (s1.n2).id = n3.id returning (n3.id, n3.kind_ids, n3.properties)::nodecomposite as n3), s3 as (select s1.e0 as e0, s1.e1 as e1, s1.n1 as n1, case when (s1.n2).id = (s2.n3).id then s2.n3 else s1.n2 end as n2 from s1 left outer join s2 on (s1.n2).id = (s2.n3).id), s4 as (update edge e2 set properties = e2.properties || jsonb_build_object(@__strlit0::text, true)::jsonb from s3 where (s3.e1).id = e2.id returning (e2.id, e2.start_id, e2.end_id, e2.kind_id, e2.properties)::edgecomposite as e2), s5 as (select s3.e0 as e0, case when (s3.e1).id = (s4.e2).id then s4.e2 else s3.e1 end as e1, s3.n1 as n1, s3.n2 as n2 from s3 left outer join s4 on (s3.e1).id = (s4.e2).id) select s5.n2 as c from s5;

-- case: MATCH (a)-[:EdgeKind1]->(b)-[:EdgeKind2]-(c) CREATE (:NodeKind1 {target:c.name})
-- pgsql_params:{"__strlit0":"node","__strlit1":"id","__strlit2":"target"}
with s0 as (select e0.id as e0, n1.id as n1 from edge e0 join node n0 on n0.id = e0.start_id join node n1 on n1.id = e0.end_id where e0.kind_id = any (array [3]::int2[])), s1 as (select s0.e0 as e0, s0.n1 as n1, (n2.id, n2.kind_ids, n2.properties)::nodecomposite as n2 from s0 join edge e1 on (s0.n1 = e1.start_id or s0.n1 = e1.end_id) join node n2 on ((s0.n1 = e1.start_id and n2.id = e1.end_id) or (n2.id = e1.start_id and s0.n1 = e1.end_id)) where e1.kind_id = any (array [4]::int2[]) and e1.id != s0.e0), s2 as (select s1.e0 as e0, s1.n1 as n1, s1.n2 as n2, nextval(pg_get_serial_sequence(@__strlit0::text, @__strlit1::text))::int8 as n3_id from s1), s3 as (insert into node (graph_id, id, kind_ids, properties) select 0, s2.n3_id, array [1]::int2[], jsonb_build_object(@__strlit2::text, ((s2.n2).properties ->> E'name'))::jsonb from s2 returning id as n3_id, (id, kind_ids, properties)::nodecomposite as n3), s4 as (select s2.e0 as e0, s2.n1 as n1, s2.n2 as n2, s3.n3 as n3 from s2, s3 where s3.n3_id = s2.n3_id) select 1;
